namespace Kairnfall.Core;

/// <summary>Bounded region populations. Existing save identities and timers remain unchanged.</summary>
public static class WorldPopulation
{
    public sealed record Spawn(string Id,string Template,Point Position);
    public static bool AmbientChestEnabled(ZoneDef zone,int index)
    {
        if(index<0||index>2) return false;
        if(zone.Id=="wayfarers_rest") return index==0;
        if(zone.Kind is "city" or "settlement" or "interior") return false;
        if(zone.Kind=="dungeon"||zone.Layer!="Surface") return index<2;
        return index==2;
    }
    public static bool ChestEnabled(Chest chest,Catalog data)
    {
        string prefix=chest.Zone+"/chest/";
        if(!chest.Id.StartsWith(prefix,StringComparison.Ordinal)) return true;
        string suffix=chest.Id[prefix.Length..];
        if(suffix is not ("0" or "1" or "2")) return true;
        return AmbientChestEnabled(data.Zone(chest.Zone),int.Parse(suffix,System.Globalization.CultureInfo.InvariantCulture));
    }
    public static IReadOnlyList<Spawn> AdditionalSpawns(ZoneDef zone,Catalog data)
    {
        if(zone.Kind is "city" or "interior"||(zone.Kind=="settlement"&&zone.Id!="wayfarers_rest")) return [];
        var available=zone.Species.Select(data.Mob).Where(mob=>!mob.Boss&&!mob.Elite).OrderBy(mob=>mob.Level).ThenBy(mob=>mob.Id,StringComparer.Ordinal).ToArray();
        if(available.Length==0) return [];
        var eligible=available.Where(mob=>mob.Level<=zone.Level+8).ToArray();
        if(eligible.Length==0) eligible=[available[0]];
        int desired=zone.Id=="wayfarers_rest"?8:zone.Kind=="dungeon"?8:12;
        int count=Math.Clamp(desired-available.Length,0,12);
        var result=new List<Spawn>();
        for(int index=0;index<count;index++)
        {
            for(int attempt=0;attempt<160;attempt++)
            {
                uint value=WorldMap.Hash(index,attempt,zone.Seed+17071);
                double angle=value%6283/1000.0;
                double minimum=zone.Id=="wayfarers_rest"?20:zone.Kind=="dungeon"?7:10;
                double span=zone.Id=="wayfarers_rest"?9:zone.Kind=="dungeon"?8:16;
                double radius=minimum+(value/6283)%1000/1000.0*span;
                var position=new Point(zone.Spawn.X+Math.Cos(angle)*radius,zone.Spawn.Y+Math.Sin(angle)*radius);
                if(!WorldMap.Fits(zone,position)||zone.Exits.Any(exit=>exit.Position.Distance(position)<3)
                    ||data.Npcs.Any(npc=>npc.Zone==zone.Id&&npc.Position.Distance(position)<7)
                    ||result.Any(spawn=>spawn.Position.Distance(position)<2.5)) continue;
                var mob=eligible[index%eligible.Length];
                result.Add(new Spawn(zone.Id+"/population/v1/"+index,mob.Id,position));
                break;
            }
        }
        return result;
    }
}

