using Kairnfall.Core;

public static class PopulationCases
{
    public static void Run(Action<string,Action> test,Catalog data)
    {
        void Check(bool value,string message) {if(!value) throw new InvalidOperationException(message);}
        test("Population plans are deterministic bounded and on valid terrain",()=>
        {
            foreach(var zone in data.Zones)
            {
                var spawns=WorldPopulation.AdditionalSpawns(zone,data);
                Check(spawns.SequenceEqual(WorldPopulation.AdditionalSpawns(zone,data)),"Spawn plans changed.");
                Check(spawns.Count<=12&&spawns.Select(x=>x.Id).Distinct().Count()==spawns.Count,"Spawn bounds or identities failed.");
                foreach(var spawn in spawns)
                {
                    Check(WorldMap.Fits(zone,spawn.Position),"Population spawned inside solid terrain.");
                    Check(zone.Exits.All(exit=>exit.Position.Distance(spawn.Position)>=3),"Population blocks an exit.");
                    Check(data.Npcs.All(npc=>npc.Zone!=zone.Id||npc.Position.Distance(spawn.Position)>=7),"Population overlaps service staff.");
                    Check(!data.Mob(spawn.Template).Boss&&!data.Mob(spawn.Template).Elite,"Population duplicated a boss or elite.");
                }
            }
        });
        test("Safe cities and interiors receive no hostile population additions",()=>
        {
            foreach(var zone in data.Zones.Where(zone=>zone.Kind is "city" or "interior"))
                Check(WorldPopulation.AdditionalSpawns(zone,data).Count==0,"Safe area received hostile additions.");
            Check(WorldPopulation.AdditionalSpawns(data.Zone("wayfarers_rest"),data).Count>=3,"Starter outskirts were not populated.");
            Check(WorldPopulation.AdditionalSpawns(data.Zone("kingsmeadow"),data).Count>=6,"Early wilderness remains sparse.");
        });
        test("Reloading population preserves death and respawn timers without duplication",()=>
        {
            var realm=new RealmEngine(data);
            var mob=realm.State.Creatures.Values.First(x=>x.Id.Contains("/population/v1/",StringComparison.Ordinal));
            mob.Health=0; mob.RespawnAt=realm.State.Time+123; int count=realm.State.Creatures.Count;
            var loaded=new RealmEngine(data,Wire.Copy(realm.State));
            Check(loaded.State.Creatures.Count==count,"Reload duplicated population.");
            Check(loaded.State.Creatures[mob.Id].Health==0&&loaded.State.Creatures[mob.Id].RespawnAt==mob.RespawnAt,"Reload reset a saved creature.");
        });
        test("Ambient chest policy makes cities empty and starter caches uncommon",()=>
        {
            var realm=new RealmEngine(data);
            Check(realm.State.Chests.Values.Count(x=>x.Zone=="wayfarers_rest")==1,"Starter chest count is not one.");
            Check(!realm.State.Chests.Values.Any(x=>data.Zone(x.Zone).Kind is "city" or "interior"),"Services contain ambient chests.");
            Check(realm.State.Chests.Count<data.Zones.Count*2,"Ambient chests are oversaturated.");
        });
        test("Retired legacy caches retain saved data but cannot be listed or looted",()=>
        {
            var realm=new RealmEngine(data); var player=realm.CreateCharacter("cache-account","Cache Fixture","vanguard",new());
            var chest=new Chest {Id=player.Zone+"/chest/1",Zone=player.Zone,Position=player.Position,Kind="locked",Requirement=1,ReadyAt=42};
            realm.State.Chests[chest.Id]=chest;
            var loaded=new RealmEngine(data,Wire.Copy(realm.State)); long gold=loaded.Player(player.Id).Gold;
            Check(loaded.State.Chests[chest.Id].Kind=="locked"&&loaded.State.Chests[chest.Id].ReadyAt==42,"Legacy data was overwritten.");
            Check(!loaded.Snapshot(player.Id).Chests.Any(x=>x.Id==chest.Id),"Retired cache remains visible.");
            Check(!loaded.Execute(player.Id,new GameCommand{Kind="chest",Target=chest.Id,Sequence=1}).Ok,"A guessed legacy ID yielded loot.");
            Check(loaded.Player(player.Id).Gold==gold,"Rejected legacy loot changed gold.");
        });
        test("Special caches are not retired by ambient policy",()=>
        {
            var zone=data.Zone("wayfarers_rest");
            foreach(string id in new[]{"event/special/cache","treasure/map/cache",zone.Id+"/chest/special"})
                Check(WorldPopulation.ChestEnabled(new Chest{Id=id,Zone=zone.Id},data),"Nonambient reward was removed.");
        });
    }
}
